$('native-civic-conflict-file').onchange=async event=>{
 const input=event.target,file=input.files[0];input.value='';
 if(!file||busy||civicConflictRead)return;
 const ticket=++civicConflictSequence,expected=++revision,label=$('native-civic-conflict-label').value;
 civicConflictRead=ticket;invalidateReportResult();
 try{
  const next=await appendNativeCivicConflictFile(files.nativeCivicConflictInputs||{sources:[]},label,file);
  if(ticket!==civicConflictSequence||expected!==revision||busy)return;
  setNativeCivicConflicts(next.sources);$('native-civic-conflict-label').value='';
 }catch(error){if(ticket===civicConflictSequence&&expected===revision)showError(error.message);}
 finally{if(civicConflictRead===ticket){civicConflictRead=0;updateImportControls();}}
};
