function retireNativeNarrativeIntent(){
 $('native-narrative-name').value='';
 $('native-narrative-confirm').checked=false;
 $('native-narrative-cross-year').checked=false;
}
function syncNativeNarrativeForm(inputs){
 const value=inputs||NATIVE_NARRATIVE_DEFAULTS;
 $('native-narrative-format').value=value.format;
 $('native-narrative-threshold').value=String(value.leaning_threshold*100);
 $('native-narrative-band').value=String(value.close_call_band*100);
 $('native-narrative-epoch').value=value.source_date_epoch??'';
 for(const side of ['a','b'])$('native-narrative-'+side).value='';
 retireNativeNarrativeIntent();
}
function nativeNarrativeForm(){
 const threshold=$('native-narrative-threshold').value,band=$('native-narrative-band').value;
 if(!threshold||!band)throw new Error('Supply both report percentages.');
 return validateNativeNarrativeInputs({...NATIVE_NARRATIVE_DEFAULTS,...files.nativeNarrativeInputs,
  format:$('native-narrative-format').value,leaning_threshold:Number(threshold)/100,close_call_band:Number(band)/100,
  source_date_epoch:$('native-narrative-epoch').value||null});
}
function nativeNarrativeRunRequest(){
 if(nativeNarrativeReading)throw new Error('Wait for the selected folder to finish reading.');
 const settings=nativeNarrativeForm(),name=$('native-narrative-name').value;
 const confirmed=$('native-narrative-confirm').checked;
 if((name||confirmed)&&(!confirmed||!nativeNarrativePlain(name)))throw new Error('Confirm a plain sign-off name for this run or clear the name for a draft.');
 const request=nativeNarrativeRequest(settings,{signoff:confirmed?name:null,allowCrossYear:$('native-narrative-cross-year').checked});
 files.nativeNarrativeInputs=settings;
 retireNativeNarrativeIntent();
 return request;
}
