// Fresh native runs have an independent worker, but share the normal project
// persistence. Retained imported results remain data, never current run grants.
function refreshFreshStateProjectControls(){
 freshNativeStatePanel?.setExternalBusy(busy||configCatalogLoading);
 const active=freshNativeStatePanel?.isBusy()??false;
 for(const name of ['execute','flow-run','save-project','save-workbench-archive','open-project','open-workbench-archive','restore-project']){
  const node=document.getElementById(name);if(!node)continue;
  if(active){if(!freshStateProjectLocks.has(node))freshStateProjectLocks.set(node,node.disabled);node.disabled=true;}
  else if(freshStateProjectLocks.has(node)){node.disabled=freshStateProjectLocks.get(node);freshStateProjectLocks.delete(node);}
 }
}
freshNativeStatePanel?.subscribe({
 onChange:value=>{if(value)files.freshNativeStateSession=value;else delete files.freshNativeStateSession;autosave(true);},
 onHandoff:({action,inputs})=>{
  if(busy||configCatalogLoading||freshNativeStatePanel.isBusy())throw Error('Wait for the active workbench action before selecting a follow-up.');
  if(!['audit','analyze','improve'].includes(action))throw Error('Unsupported fresh State follow-up.');
  revision++;invalidateReportResult();Object.assign(files,inputs);delete files.auditCertificateText;delete files.auditLineageText;
  for(const key of ['auditPlanText','auditContextText','auditCertificateText','auditLineageText'])$(key+'-file').value='';
  $('operation').value=action==='audit'?'audit-rplan-text':action==='improve'?'improve-rplan-text':'analyze-plan-package';
  if(action==='improve'){$('improvement-tolerance').value=inputs.improvementSettings.tolerance_percent;$('improvement-label').value=inputs.improvementSettings.label||'';$('improvement-time').value=inputs.improvementSettings.generated_at_utc;}
  autosave();$('result-status').textContent='Fresh native plan and context selected. Select any required profile or additional sources, then Execute '+action+' explicitly. No analysis, audit or improvement ran during selection.';
  updateFields();updateImportControls();
 },
 onBusy:value=>{if(!value){freshStateProjectLocks.delete($('execute'));freshStateProjectLocks.delete($('flow-run'));$('execute').disabled=busy||!ready||configCatalogLoading;}updateImportControls();}
});
